-- 0003: one source, three views. Canonical chapters (topics.is_chapter) + questions.chapter_id. Additive only.
alter table mtb.topics add column if not exists is_chapter boolean not null default false;
alter table mtb.topics add column if not exists unit_en text;
alter table mtb.topics add column if not exists unit_hi text;
alter table mtb.questions add column if not exists chapter_id int references mtb.topics(id);
create index if not exists questions_chapter_idx on mtb.questions(chapter_id) where status = 'published';
insert into mtb.topics(subject_id,slug,name_en,name_hi,unit_en,unit_hi,sort,is_chapter)
select (select id from mtb.subjects where slug='general-science'), v.slug, v.en, v.hi, v.uen, v.uhi, v.sort, true
from (values
('phy-measurement','Measurement & Units','माप और मात्रक','Physics','भौतिकी',0),
('phy-motion','Motion','गति','Physics','भौतिकी',1),
('phy-force','Force & Laws of Motion','बल और गति के नियम','Physics','भौतिकी',2),
('phy-work-energy','Work, Energy & Power','कार्य, ऊर्जा और शक्ति','Physics','भौतिकी',3),
('phy-gravitation','Gravitation','गुरुत्वाकर्षण','Physics','भौतिकी',4),
