) v(slug,en,hi,uen,uhi,sort) on conflict (subject_id, slug) do nothing;
update mtb.topics set is_chapter = true where id not in (29,30,31,32,413,414,420,33,34,35,36,37,39,20,21,22,23,24,25,26) and is_chapter = false;
update mtb.topics set name_en='Alphabet & Alphanumeric Series', name_hi='वर्णमाला और अक्षर-अंक श्रृंखला' where id=423;
update mtb.topics set name_en='Science & Technology', name_hi='विज्ञान और प्रौद्योगिकी' where id=40;
update mtb.topics set name_hi='कला और संस्कृति' where id=38 and name_hi is null;
-- plain topics that are already chapters
update mtb.questions q set chapter_id = q.topic_id from mtb.topics t where t.id = q.topic_id and t.is_chapter and q.chapter_id is null;
-- duplicate topics → canonical chapter
update mtb.questions set chapter_id = case topic_id when 33 then 416 when 34 then 421 when 35 then 419 when 36 then 418 when 37 then 417 when 39 then 422
  when 20 then 426 when 21 then 425 when 22 then 427 when 23 then 428 when 24 then 423 when 25 then 429 when 26 then 431 end
where topic_id in (33,34,35,36,37,39,20,21,22,23,24,25,26) and chapter_id is null;
-- environment
update mtb.questions set chapter_id = (select t.id from mtb.topics t join mtb.subjects s on s.id=t.subject_id where s.slug='general-science' and t.slug='env-ecology') where topic_id = 32 and chapter_id is null;
